export const hairStyles=[{id:'short',name:'Cheveux courts'},{id:'bob',name:'Carré'},{id:'curls',name:'Boucles'},{id:'ponytail',name:'Queue de cheval'},{id:'crest',name:'Mèche relevée'}];
export const tops=[{id:'tee',name:'T-shirt lagon',color:0x33a99b},{id:'sun',name:'Marinière soleil',color:0xe3c657},{id:'jacket',name:'Veste corail',color:0xec9360},{id:'crystal',name:'Veste des cristaux',color:0x8b79c9,unlock:'crystal'},{id:'safari',name:'Chemise safari',color:0xcbb484,unlock:'safari'}];
export const bottoms=[{id:'jeans',name:'Pantalon bleu',color:0x354d69},{id:'shorts',name:'Short sable',color:0xc4a27b},{id:'skirt',name:'Jupe prune',color:0x9163a3},{id:'ruins',name:'Pantalon des ruines',color:0x6d9274,unlock:'ruins'},{id:'snow',name:'Pantalon des sommets',color:0xd7e7ed,unlock:'snow'}];
export const outfitCaches=[{id:'ruins',x:49,z:6,name:'Pantalon des ruines'},{id:'snow',x:-22,z:-125,name:'Pantalon des sommets'}];
export function normalizeOutfits(value={},owned=[]){const available=(list,id)=>list.some(i=>i.id===id&&(!i.unlock||owned.includes(i.unlock)));return {hair:hairStyles.some(i=>i.id===value?.hair)?value.hair:'short',top:available(tops,value?.top)?value.top:'tee',bottom:available(bottoms,value?.bottom)?value.bottom:'jeans'};}
export function unlockOutfit(state,id){if(!['crystal','safari','ruins','snow'].includes(id)||state.owned.includes(id))return false;state.owned.push(id);return true;}
export function syncOutfits(state,progress){let changed=false;if(progress.crystal)changed=unlockOutfit(state,'crystal')||changed;if(progress.safari)changed=unlockOutfit(state,'safari')||changed;return changed;}
export function choosePlayerLook(state,category,id){const list=category==='hair'?hairStyles:category==='top'?tops:category==='bottom'?bottoms:[];const item=list.find(i=>i.id===id);if(!item||item.unlock&&!state.owned.includes(item.unlock))return false;state[category]=id;return true;}
